    p=subprocess.run(['curl','-fsS','-H','Accept: application/json',u],text=True,capture_output=True)
    if p.returncode: by[rs]={}; print(rs,'no associations'); continue
    d=json.loads(p.stdout); arr=d.get('_embedded',{}).get('associations',[]); m={}
    for a in arr:
      aid=a['_links']['self']['href'].rstrip('/').split('/')[-1]
      q=subprocess.run(['curl','-fsS','-H','Accept: application/json',f'https://www.ebi.ac.uk/gwas/rest/api/associations/{aid}/study'],text=True,capture_output=True)
      if q.returncode: continue
      st=json.loads(q.stdout); acc=st.get('accessionId')
      if acc: m[acc]=(a.get('pvalue'),st.get('publicationInfo',{}).get('pubmedId'),st.get('diseaseTrait',{}).get('trait'))
    by[rs]=m; print(rs,len(m))
common=set.intersection(*(set(x) for x in by.values()))
print('COMMON ALL',sorted(common))
for acc in sorted(set.union(*(set(x) for x in by.values()))):
    hits=[rs for rs in rsids if acc in by[rs]]
    if len(hits)>=2:
      print(acc,len(hits),hits,[(rs,by[rs][acc]) for rs in hits])
