import json, urllib.request, concurrent.futures
for rs in ['rs7554873','rs4561508','rs4273077','rs4985726','rs143596860']:
    url=f'https://www.ebi.ac.uk/gwas/rest/api/singleNucleotidePolymorphisms/{rs}/associations?projection=associationBySnp&page=0&size=100'
    try:
      with urllib.request.urlopen(url) as f: data=json.load(f)
    except Exception as e:
      print('ERROR',rs,e); continue
    def one(a):
      with urllib.request.urlopen(a['_links']['study']['href']+'?projection=associationByStudy') as f: s=json.load(f)
      pub=s.get('publicationInfo',{})
      trait=';'.join(t.get('trait','') for t in a.get('efoTraits',[])) or s.get('diseaseTrait',{}).get('trait','')
      return (s.get('accessionId',''),str(pub.get('pubmedId','')),trait,str(a.get('pvalue','')))
    with concurrent.futures.ThreadPoolExecutor(max_workers=12) as ex: rows=list(ex.map(one,data.get('_embedded',{}).get('associations',[])))
    print('###',rs)
    for row in sorted(set(rows)): print('\\t'.join(row))
